/* Operational build controls: authenticated instructor drafts, never public previews. */
let studioBuild=null;
const sourceStudioShow=ssShow;
ssShow=function(d){sourceStudioShow(d);document.getElementById('ss-detail').insertAdjacentHTML('beforeend',`<section class="card prose"><h2>Generate and export</h2><p>Build from the current source revision. Instructor edits are preserved. For separate editions, enter draft text as JSON with student, instructor, sourceIds and supplemental fields.</p><button class="button" data-build-action="generate">Generate package</button> <button class="button secondary" data-build-action="assemble">Build from authored editions</button><p id="build-status" role="status"></p><div id="build-list"></div><div id="build-detail"></div></section>`);loadStudioBuilds();};
async function loadStudioBuilds(){try{const [status,list]=await Promise.all([workspaceApi('studio-builds/status'),workspaceApi('studio-builds/list')]);document.getElementById('build-status').textContent=`Hosted model: ${status.hostedConfigured?'configured (not yet verified)':'not configured'}. ${status.media}. Lab image: ${status.labImageConfigured?'configured':'not configured'}.`;document.getElementById('build-list').innerHTML=list.builds.filter(x=>x.module===ssCurrent.id).map(x=>`<p><button class="button secondary" data-open-build="${esc(x.id)}">Revision ${x.revision} · ${esc(x.status)}</button></p>`).join('');}catch(e){document.getElementById('build-status').textContent=e.message;}}
function showStudioBuild(b){studioBuild=b;const p=b.payload;document.getElementById('build-detail').innerHTML=`<h3>Build ${esc(b.id)}</h3><p>${esc(b.status)} · source revision ${b.revision}</p><p>Instructor review: optional. ${b.releasePolicy?.releaseAllowed?'Complete current build: eligible for release.':esc((b.releasePolicy?.technicalBlockers||[]).join('; '))} Publication integration is not available.</p><p>Package hash: <code>${esc(p.hash||'Build running')}</code></p>${p.errors.map(e=>`<p>${esc(e.output)}: ${esc(e.message)}</p>`).join('')}<label>Preview edition<select id="build-edition"><option value="student">Student</option><option value="instructor">Instructor</option></select></label><div id="build-preview"></div><button class="button secondary" data-download-build="student">Download student package</button> <button class="button secondary" data-download-build="instructor">Download instructor package</button><h3>Optional review</h3><p>Review is optional and does not block exports or release eligibility. Review records remain attached to the version that was inspected.</p><form id="studio-review"><label>Assigned capacity<select name="capacity"><option value="subject-matter-expert">Subject-matter expert</option><option value="instructional-designer">Instructional designer</option></select></label><label>Decision<select name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option></select></label><label>Review evidence<textarea name="evidence" minlength="20" maxlength="4000" required></textarea></label><button class="button">Record review</button></form><ul>${(b.reviews||[]).map(r=>`<li>${esc(r.capacity)} · ${esc(r.reviewer)} · ${esc(r.decision)}: ${esc(r.evidence)}</li>`).join('')}</ul>`;previewStudioEdition();}
function previewStudioEdition(){const edition=document.getElementById('build-edition').value;document.getElementById('build-preview').innerHTML=studioBuild.payload.outputs.map(o=>`<details><summary>${esc(o.id)} · ${esc(o.origin)}</summary><p>AI-assisted content.</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(o.content[edition])}</pre>${o.lab?`<p>Lab execution: ${esc(o.lab.status)} ${esc(o.lab.reason||'')}</p>`:''}</details>`).join('');}
document.addEventListener('change',e=>{if(e.target.id==='build-edition')previewStudioEdition();});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-build-action],[data-open-build],[data-download-build]');if(!b)return;b.disabled=true;try{if(b.dataset.buildAction){document.getElementById('build-status').textContent='Building versioned outputs. This may take several minutes with a hosted model.';const r=await workspaceApi('studio-builds/'+b.dataset.buildAction,{id:ssCurrent.id,revision:ssCurrent.revision});await loadStudioBuilds();showStudioBuild(await workspaceApi('studio-builds/get',{build:r.build}));}else if(b.dataset.openBuild){showStudioBuild(await workspaceApi('studio-builds/get',{build:b.dataset.openBuild}));}else{const r=await workspaceApi('studio-builds/download',{build:studioBuild.id,edition:b.dataset.downloadBuild});const bytes=Uint8Array.from(atob(r.base64),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'}));const a=document.createElement('a');a.href=url;a.download=r.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(err){document.getElementById('build-status').textContent=err.message;}finally{b.disabled=false;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='studio-review')return;e.preventDefault();try{await workspaceApi('studio-builds/review',{build:studioBuild.id,...Object.fromEntries(new FormData(e.target))});showStudioBuild(await workspaceApi('studio-builds/get',{build:studioBuild.id}));}catch(err){document.getElementById('build-status').textContent=err.message;}});
